  4	final class IntBinaryHeap {
  5	    private static final int DEFAULT_CAPACITY = 10;
  6	
  7	    private int[] elements;
  8	    private int size;
  9	
 10	    IntBinaryHeap() {
 11	        this(DEFAULT_CAPACITY);
 12	    }
 13	
 14	    IntBinaryHeap(int initialCapacity) {
 15	        if (initialCapacity < 0) {
 16	            throw new IllegalArgumentException("initial capacity must be non-negative");
 17	        }
 18	
 19	        elements = new int[initialCapacity];
 20	        size = 0;
 21	    }
 22	
 23	    IntBinaryHeap(int[] values) {
 24	        if (values == null) {
 25	            throw new IllegalArgumentException("values must not be null");
 26	        }
 27	
 28	        elements = Arrays.copyOf(values, values.length);
 29	        size = values.length;
 30	        heapify();
 31	    }
 32	
 33	    boolean offer(int value) {
 34	        ensureCapacity(size + 1);
 35	        elements[size] = value;
 36	        siftUp(size);
 37	        size++;
 38	        return true;
 39	    }
 40	
 41	    int peek() {
 42	        ensureNotEmpty();
 43	        return elements[0];
 44	    }
 45	
 46	    int removeMin() {
 47	        ensureNotEmpty();
 48	        return removeAt(0);
 49	    }
 50	
 51	    int extractMin() {
 52	        if (isEmpty()) {
 53	            return Integer.MAX_VALUE;
 54	        }
 55	
 56	        return removeMin();
 57	    }
 58	
 59	    int removeAt(int index) {
 60	        validateOccupiedIndex(index);
 61	
 62	        int removedValue = elements[index];
 63	        int lastIndex = size - 1;
 64	        int lastValue = elements[lastIndex];
 65	        elements[lastIndex] = 0;
 66	        size--;
 67	        if (index == lastIndex) {
 68	            return removedValue;
 69	        }
 70	
 71	        elements[index] = lastValue;
 72	        restoreHeapAt(index);
 73	        return removedValue;
 74	    }
 75	
 76	    void updateValue(int index, int newValue) {
 77	        validateOccupiedIndex(index);
 78	
 79	        int currentValue = elements[index];
 80	        elements[index] = newValue;
 81	        if (newValue < currentValue) {
 82	            siftUp(index);
 83	            return;
 84	        }
 85	
 86	        if (newValue > currentValue) {
 87	            siftDown(index);
 88	        }
 89	    }
 90	
 91	    void decreaseKey(int index, int newValue) {
 92	        validateOccupiedIndex(index);
 93	        ensureValueDecreases(index, newValue);
 94	        updateValue(index, newValue);
 95	    }
 96	
 97	    void increaseKey(int index, int newValue) {
 98	        validateOccupiedIndex(index);
 99	        ensureValueIncreases(index, newValue);
100	        updateValue(index, newValue);
101	    }
102	
103	    void clear() {
104	        Arrays.fill(elements, 0, size, 0);
105	        size = 0;
106	    }
107	
108	    boolean isEmpty() {
109	        return size == 0;
110	    }
111	
112	    boolean isFull() {
113	        return size == elements.length;
114	    }
115	
116	    int size() {
117	        return size;
118	    }
119	
120	    int capacity() {
121	        return elements.length;
122	    }
123	
124	    int valueAt(int index) {
125	        validateOccupiedIndex(index);
126	        return elements[index];
127	    }
128	
129	    int[] toArray() {
130	        return Arrays.copyOf(elements, size);
131	    }
132	
133	    private void heapify() {
134	        for (int index = parentIndex(size - 1); index >= 0; index--) {
135	            siftDown(index);
136	        }
137	    }
138	
139	    private void ensureCapacity(int requiredCapacity) {
140	        if (requiredCapacity <= elements.length) {
141	            return;
142	        }
143	
144	        int newCapacity = elements.length == 0 ? 1 : elements.length;
145	        while (newCapacity < requiredCapacity) {
146	            newCapacity *= 2;
147	        }
148	
149	        elements = Arrays.copyOf(elements, newCapacity);
150	    }
151	
152	    private void siftUp(int index) {
153	        while (index > 0) {
154	            int parentIndex = parentIndex(index);
155	            if (elements[parentIndex] <= elements[index]) {
156	                return;
157	            }
158	
159	            swap(index, parentIndex);
160	            index = parentIndex;
161	        }
162	    }
163	
164	    private void siftDown(int index) {
165	        while (true) {
166	            int leftChildIndex = leftChildIndex(index);
167	            int rightChildIndex = rightChildIndex(index);
168	            int smallestIndex = index;
169	
170	            if (leftChildIndex < size && elements[leftChildIndex] < elements[smallestIndex]) {
171	                smallestIndex = leftChildIndex;
172	            }
173	
174	            if (rightChildIndex < size && elements[rightChildIndex] < elements[smallestIndex]) {
175	                smallestIndex = rightChildIndex;
176	            }
177	
178	            if (smallestIndex == index) {
179	                return;
180	            }
181	
182	            swap(index, smallestIndex);
183	            index = smallestIndex;
184	        }
185	    }
186	
187	    private void restoreHeapAt(int index) {
188	        if (index > 0 && elements[index] < elements[parentIndex(index)]) {
189	            siftUp(index);
190	            return;
191	        }
192	
193	        siftDown(index);
194	    }
195	
196	    private void swap(int firstIndex, int secondIndex) {
197	        int temp = elements[firstIndex];
198	        elements[firstIndex] = elements[secondIndex];
199	        elements[secondIndex] = temp;
200	    }
201	
202	    private void ensureNotEmpty() {
203	        if (isEmpty()) {
204	            throw new NoSuchElementException("heap is empty");
205	        }
206	    }
207	
208	    private void validateOccupiedIndex(int index) {
209	        if (index < 0 || index >= size) {
210	            throw new IndexOutOfBoundsException(
211	                "index " + index + " is outside heap size " + size
212	            );
213	        }
214	    }
215	
216	    private void ensureValueDecreases(int index, int newValue) {
217	        if (newValue > elements[index]) {
218	            throw new IllegalArgumentException(
219	                "new value " + newValue + " is greater than current value " + elements[index]
220	            );
221	        }
222	    }
223	
224	    private void ensureValueIncreases(int index, int newValue) {
225	        if (newValue < elements[index]) {
226	            throw new IllegalArgumentException(
227	                "new value " + newValue + " is less than current value " + elements[index]
228	            );
229	        }
230	    }
231	
232	    private int parentIndex(int index) {
233	        return (index - 1) / 2;
234	    }
235	
236	    private int leftChildIndex(int index) {
237	        return index * 2 + 1;
238	    }
239	
240	    private int rightChildIndex(int index) {
241	        return index * 2 + 2;
242	    }
243	}
